import calendar
import datetime


def add_months(day, months):
    """The date `months` months after `day`, clamped to the end of the month. See TASK.md."""
    if isinstance(months, bool) or not isinstance(months, int):
        raise TypeError("months must be an int and not a bool")
    if not isinstance(day, datetime.date):
        raise TypeError("day must be a datetime.date")

    total = day.month - 1 + months
    year = day.year + total // 12
    month = total % 12 + 1

    if year < 1 or year > 9999:
        raise ValueError("result is outside the supported year range 1-9999")

    last = calendar.monthrange(year, month)[1]
    dom = min(day.day, last)
    return datetime.date(year, month, dom)


def months_between(start, end):
    """Whole months from `start` to `end`. See TASK.md."""
    if start > end:
        return -months_between(end, start)

    lo = 0
    hi = 1
    # Grow hi until add_months(start, hi) exceeds end (or overflows).
    while True:
        try:
            if add_months(start, hi) <= end:
                hi *= 2
            else:
                break
        except ValueError:
            break

    # Largest n in [lo, hi] with add_months(start, n) <= end.
    while lo < hi:
        mid = (lo + hi + 1) // 2
        try:
            if add_months(start, mid) <= end:
                lo = mid
            else:
                hi = mid - 1
        except ValueError:
            hi = mid - 1
    return lo
